import sys

def dist_brute(a, b):
    m, n = len(a), len(b)
    memo = {}
    def f(i, j):
        if i == 0: return j
        if j == 0: return i
        if (i, j) in memo: return memo[(i, j)]
        if a[i - 1] == b[j - 1]:
            memo[(i, j)] = f(i - 1, j - 1)
        else:
            memo[(i, j)] = 1 + min(f(i - 1, j), f(i, j - 1), f(i - 1, j - 1))
        return memo[(i, j)]
    return f(m, n)

if __name__ == '__main__':
    lines = sys.stdin.read().splitlines()
    if not lines:
        sys.exit(0)
    a = lines[0].rstrip()
    b = lines[1].rstrip() if len(lines) > 1 else ''
    print(dist_brute(a, b))

import sys

def dist_opt(a, b):
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1])
    return dp[m][n]

if __name__ == '__main__':
    lines = sys.stdin.read().splitlines()
    if not lines:
        sys.exit(0)
    a = lines[0].rstrip()
    b = lines[1].rstrip() if len(lines) > 1 else ''
    print(dist_opt(a, b))

import sys

def dist_best(a, b):
    m, n = len(a), len(b)
    if m < n:
        a, b, m, n = b, a, n, m
    dp = list(range(n + 1))
    for i in range(1, m + 1):
        cur = dp[:]
        cur[0] = i
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                cur[j] = dp[j - 1]
            else:
                cur[j] = 1 + min(dp[j], cur[j - 1], dp[j - 1])
        dp = cur
    return dp[n]

if __name__ == '__main__':
    lines = sys.stdin.read().splitlines()
    if not lines:
        sys.exit(0)
    a = lines[0].rstrip()
    b = lines[1].rstrip() if len(lines) > 1 else ''
    print(dist_best(a, b))
